// [contracts] src/lib/studio-projects/drafts/types.ts (types + constants + the error class; imports only userScope types)
export const DRAFT_DB_NAME = 'ma-studio';
export const DRAFT_STORES = ['drafts', 'bodies', 'media', 'quarantine', 'meta'] as const; // 'takes', 'assets' reserved
export type DraftOrigin = 'session' | 'kept' | 'fork' | 'migrated' | 'recovered';
export type DraftSourceKind = 'empty' | 'new' | 'template' | 'demo' | 'tutorial' | 'song' | 'practiceMode' | 'practiceGenre' | 'jam' | 'collab' | 'project' | 'import';
export interface DraftBaseline { source: DraftSourceKind; ref?: string; reopenable: boolean; fingerprint: string | null }
export interface DraftCloudRecord { projectId: string; updatedAt: string | null /* server ISO; compared only with server values */; savedFingerprint: string; savedComplete: boolean; savedAt: number; revision?: number; documentSchema?: number }
export interface DraftMediaRef { mediaId: string /* sha-256 hex */; contentType: string; size: number; clipIds: string[]; samplerSampleIds: string[] }
export interface DraftContext { tutorial?: { id: string; stepIndex: number }; practiceSession?: unknown; studentTrackId?: string } // 1.15
export interface DraftMeta {
  v: 1; draftId: string; userKey: UserKey; origin: DraftOrigin;
  createdAt: number; updatedAt: number; keptAt?: number;
  writeSeq: number; writer: { build: string; doc: string };
  schema: number;                 // body "schema" (2 when absent); > SESSION_SCHEMA_VERSION = read-only
  projectId?: string;             // wins over the body's data.projectId on open
  roomId?: string;
  name: string; trackCount: number; chars: number;
  docFingerprint: string | null;  // hashFingerprint(documentFingerprint()); null = unknown (counts as work)
  hasContent: boolean;            // differs from the empty project's fingerprint
  baseline: DraftBaseline; cloud?: DraftCloudRecord;
  media: DraftMediaRef[];         // stored media only
  mediaMissing: number;
  context?: DraftContext; forkedFrom?: string; claimedFrom?: UserKey;
}
export interface DraftBody { draftId: string; writeSeq: number; text: string } // 1.3 v3-in-v2 envelope JSON, verbatim
export interface DraftMediaRecord { key: string /* `${userKey}:${mediaId}` */; mediaId: string; userKey: UserKey; blob: Blob; contentType: string; size: number; createdAt: number; durationSeconds?: number; sampleRate?: number; channels?: number }
export type QuarantineSource = 'draft' | 'mirror' | 'legacy-autosave' | 'legacy-kept' | 'legacy-unreadable' | 'legacy-backup';
export interface QuarantineRecord { id?: number; userKey: UserKey; source: QuarantineSource; reason: string; schema?: number; build: string; hash: string; raw: string /* captured before any parse */; at: number; draftId?: string; name?: string }
export type DraftErrorKind = 'quota' | 'unavailable' | 'conflict' | 'not-found' | 'corrupt' | 'readonly' | 'blocked';
export class DraftStorageError extends Error { readonly kind: DraftErrorKind; constructor(kind: DraftErrorKind, message: string, options?: { cause?: unknown }) }
export interface DraftWrite { meta: Omit<DraftMeta, 'v' | 'writeSeq' | 'updatedAt' | 'writer'>; text: string; expectedSeq: number | null /* null = create */; durability?: 'strict' | 'relaxed' }
export interface DraftMetaPatch { origin?: DraftOrigin; keptAt?: number | null; projectId?: string | null; roomId?: string | null; cloud?: DraftCloudRecord | null; userKey?: UserKey; claimedFrom?: UserKey; name?: string }

// [contracts] src/lib/studio-projects/drafts/fingerprintHash.ts
export function hashFingerprint(fingerprint: string): string; // sync, stable: 'h1:' + 16 hex (two 32-bit FNV-1a lanes)
// [contracts] src/lib/studio-projects/drafts/predicates.ts (pure)
export function draftIsPristine(m: DraftMeta): boolean;   // baseline.reopenable && docFingerprint !== null && docFingerprint === baseline.fingerprint
export function draftIsCloudEqual(m: DraftMeta): boolean; // cloud?.savedComplete && docFingerprint !== null && docFingerprint === cloud.savedFingerprint && media.length === 0 && mediaMissing === 0
export function draftHasWork(m: DraftMeta): boolean;      // hasContent && !pristine && !cloudEqual
export function draftIsReadOnly(m: DraftMeta, schemaVersion: number): boolean;

// [draft-store] src/lib/studio-projects/drafts/draftStore.ts
export interface PrunePolicy { userKey: UserKey; protect: ReadonlySet<string>; reason: 'boot' | 'switch' | 'quota' | 'sign-out'; schemaVersion: number; now?: number }
export interface PruneReport { deletedDrafts: string[]; deletedMedia: number; freedChars: number }
export interface DraftStore {
  readonly kind: 'indexeddb' | 'localstorage';
  list(userKey: UserKey): Promise<DraftMeta[]>;   // newest updatedAt first; never another user's
  getMeta(draftId: string): Promise<DraftMeta | null>;
  readBody(draftId: string): Promise<DraftBody | null>;
  write(w: DraftWrite): Promise<DraftMeta>;       // CAS; resolves on transaction complete; rejects DraftStorageError
  patchMeta(draftId: string, patch: DraftMetaPatch): Promise<DraftMeta | null>;
  remove(draftId: string): Promise<void>;
  hasMedia(userKey: UserKey, mediaIds: readonly string[]): Promise<Set<string>>;
  putMedia(record: DraftMediaRecord): Promise<void>; // idempotent; localStorage adapter rejects 'unavailable'
  getMedia(userKey: UserKey, mediaId: string): Promise<DraftMediaRecord | null>;
  gcMedia(userKey: UserKey, opts?: { graceMs?: number /* 600000 */ }): Promise<number>;
  quarantine(record: Omit<QuarantineRecord, 'id'>): Promise<'stored' | 'duplicate'>;
  listQuarantine(userKey: UserKey): Promise<QuarantineRecord[]>;
  getMetaValue<T>(key: string): Promise<T | null>;
  setMetaValue<T>(key: string, value: T): Promise<void>;
  prune(policy: PrunePolicy): Promise<PruneReport>;
  usage(userKey: UserKey): Promise<{ drafts: number; chars: number; mediaBytes: number }>;
}
export function getDraftStore(): DraftStore; // page singleton; IndexedDB, else the localStorage adapter; never throws
export function createDraftStore(env: { indexedDB?: IDBFactory | null; storage?: Storage | null; now?: () => number; build?: string; writerDoc?: string }): DraftStore;
export const WRITER_DOC: string;

