// [contracts] src/daw/session/types.ts (type-only imports: CollabRole, PracticeLevel, PracticeOpenTrack, ActivitySectionId)
export type OpenSource = 'boot' | 'link' | 'menu' | 'dialog' | 'library' | 'toolbar' | 'toast' | 'panel' | 'leave-collab';
export type OpenIntent =
  | { kind: 'resume' } | { kind: 'draft'; draftId: string } | { kind: 'project'; projectId: string } | { kind: 'new' }
  | { kind: 'template'; templateId: string } | { kind: 'demo'; demoId: string } | { kind: 'tutorial'; tutorialId: string }
  | { kind: 'song'; songId: string; transpose: number /* integer -11..11 */ }
  | { kind: 'practiceMode'; mode: string; rootParam: string | null; openTrack: PracticeOpenTrack; level: PracticeLevel }
  | { kind: 'practiceGenre'; genre: string; level: number; section: ActivitySectionId }
  | { kind: 'jam' }
  | { kind: 'collab'; code: string /* 'new' */; host: boolean; jamImport: boolean; awaitHost: boolean }
  | { kind: 'rejoin'; roomId: string; role: CollabRole };
export interface OpenOptions { source: OpenSource; keep?: 'auto' | 'discard'; signal?: AbortSignal }
export type OpenPhase = 'idle' | 'waiting' | 'validating' | 'preparing' | 'keeping' | 'switching' | 'loading' | 'baselining' | 'ready' | 'failed';
export type WaitingFor = 'owner' | 'token' | 'plan' | 'host' | 'save' | 'take' | null;
export type OpenErrorKind = 'not-found' | 'no-access' | 'signed-out' | 'offline' | 'server' | 'timeout' | 'session-ended' | 'room-full' | 'version' | 'storage' | 'unreadable' | 'busy' | 'in-room' | 'unknown';
export interface OpenError { kind: OpenErrorKind; message: string /* plain, no ids or codes */; retryable: boolean; surface: 'toast' | 'panel'; cause?: unknown }
export type OpenOutcome =
  | { status: 'ready'; draftId: string; kept: DraftMeta | null; forked: boolean; generation: number }
  | { status: 'refused'; error: OpenError }            // nothing changed
  | { status: 'upgrade'; lessonId: string }            // nothing changed
  | { status: 'failed'; error: OpenError; restored: 'kept' | 'empty' }
  | { status: 'superseded' } | { status: 'cancelled' };
export interface SessionUser { userId: string | null; userKey: UserKey }
export interface DraftClaim { draftId: string; userKey: UserKey; mode: 'new' | 'existing' | 'fork'; sourceDraftId?: string; lock: DraftLock | null }
export interface PreparedDraft { claim: DraftClaim; meta: DraftMeta; body: DraftBody }
export type BootNotice = { kind: 'device-found'; count: number } | { kind: 'recovered'; name: string; draftId: string } | { kind: 'quarantined'; count: number } | { kind: 'unsaved-elsewhere'; draftId: string; name: string; at: number } | { kind: 'storage-unavailable' };
export interface DraftSessionPort { // [draft-autosave] implements: getDraftSessionPort()
  activeDraftId(): string | null;
  prepareUser(user: SessionUser, signal?: AbortSignal): Promise<BootNotice[]>; // once per page+user: import, mirror reconcile, prune, lastSeenAt
  chooseResume(user: SessionUser): Promise<string | null>; // pointer (same userKey) else newest non-read-only
  findProjectDraft(user: SessionUser, projectId: string): Promise<DraftMeta | null>; // newest unlocked, with work, no roomId
  claim(user: SessionUser, target: { draftId?: string; boot: boolean }, signal?: AbortSignal): Promise<DraftClaim>; // lock or fork plan; no id = new
  read(claim: DraftClaim): Promise<PreparedDraft>;  // validated (parse + isLoadableSession); 'not-found'|'readonly'|'corrupt' (quarantined)
  release(claim: DraftClaim): void;
  flushOutgoing(reason: string): Promise<DraftMeta | null>; // pause, settle media (3 s), strict write; throws only when the live session has work
  retireOutgoing(policy: 'auto' | 'discard'): Promise<DraftMeta | null>; // kept meta, or removed; releases the lock
  activate(claim: DraftClaim): void;                 // sync: pointer + status; writes paused
  apply(prepared: PreparedDraft): void;              // sync after reset: decode; meta.projectId wins; fork → '<name> (copy)', projectId null
  begin(baseline: DraftBaseline, extras?: { roomId?: string }): Promise<DraftMeta | null>; // first record or adopt; resumes writes
  restoreMedia(meta: DraftMeta, generation: number): Promise<void>;
  unkeep(draftId: string): Promise<void>;
  patchCloud(draftId: string, patch: { projectId?: string; cloud?: DraftCloudRecord }): Promise<void>;
  listDrafts(user: SessionUser): Promise<{ mine: DraftMeta[]; device: DraftMeta[]; quarantined: QuarantineRecord[]; locked: Set<string> }>; // re-runs the legacy import
  deleteDraft(draftId: string): Promise<'deleted' | 'refused'>; // refuses active and locked
  claimDeviceDraft(user: SessionUser, draftId: string): Promise<DraftMeta | null>;
}
export interface CollabPort { leaveRoom(): void; createAndJoinRoom(): void; joinRoom(roomId: string, role?: CollabRole, partykitHost?: string, partykitRoom?: string, roomCode?: string): void; joinRoomById(roomId: string, role?: CollabRole): void; joinRoomAwaitingHost(roomId: string): void }

